// Sync worker: pull, merge, push pending
class SyncWorker(ctx: Context, p: WorkerParameters) : CoroutineWorker(ctx, p) {
    override suspend fun doWork(): Result = try {
        val server = api.getChanges(since = store.getLastSync())
        db.withTransaction { dao.applyServerChanges(server) }
        val pending = dao.getPending()
        api.pushChanges(pending) // server resolves conflicts per policy
        dao.markSynced(pending.map { it.id })
        store.setLastSync(server.timestamp)
        Result.success()
    } catch (e: IOException) { Result.retry() }
}

