// Retry with backoff
suspend fun <T> retryIO(times: Int = 3, block: suspend () -> T): T {
    repeat(times - 1) {
        try { return block() } catch (e: IOException) { delay(200L * (it + 1)) }
    }
    return block() // last attempt throws
}

